1: const statusNode = document.querySelector("#status");
2: const form = document.querySelector("#starter-form");
3: const input = document.querySelector("#starter-name");
4: const errorNode = document.querySelector("#starter-error");
5: const list = document.querySelector("#starter-list");
6: 
7: async function request(path, options = {}) {
8:   const response = await fetch(path, {
9:     headers: { "content-type": "application/json", ...(options.headers || {}) },
10:     ...options,
11:   });
12:   if (!response.ok) throw new Error(`Request failed: ${response.status}`);
13:   return response.json();
14: }
15: 
16: function render(state) {
17:   list.replaceChildren();
18:   for (const item of state.items || []) {
19:     const row = document.createElement("li");
20:     row.textContent = item.name;
21:     list.append(row);
22:   }
23: }
24: 
25: async function load() {
26:   statusNode.textContent = "Loading";
27:   try {
28:     render(await request("/api/state"));
29:     statusNode.textContent = "Ready";
30:   } catch (error) {
31:     statusNode.textContent = error.message;
32:   }
33: }
34: 
35: form.addEventListener("submit", async (event) => {
36:   event.preventDefault();
37:   const name = input.value.trim();
38:   errorNode.textContent = name ? "" : "Name is required";
39:   if (!name) return;
40:   const current = await request("/api/state");
41:   const items = [...(current.items || []), { id: crypto.randomUUID(), name }];
42:   render(await request("/api/state", { method: "PUT", body: JSON.stringify({ items }) }));
43:   input.value = "";
44:   statusNode.textContent = "Saved";
45: });
46: 
47: document.querySelector("#refresh-button").addEventListener("click", load);
48: load();

