1: import { createServer } from "node:http";
2: import { mkdir, readFile, writeFile } from "node:fs/promises";
3: import path from "node:path";
4: import { fileURLToPath } from "node:url";
5: 
6: const here = path.dirname(fileURLToPath(import.meta.url));
7: const publicDir = path.resolve(here, "../frontend/dist");
8: const dataDir = path.resolve(here, "data");
9: const statePath = path.join(dataDir, "state.json");
10: const port = Number.parseInt(process.env.PORT || "3000", 10);
11: const host = process.env.HOST || "0.0.0.0";
12: let ready = false;
13: 
14: await mkdir(dataDir, { recursive: true });
15: try {
16:   await readFile(statePath, "utf8");
17: } catch {
18:   await writeFile(statePath, JSON.stringify({ items: [] }, null, 2));
19: }
20: ready = true;
21: 
22: async function readState() {
23:   return JSON.parse(await readFile(statePath, "utf8"));
24: }
25: 
26: async function readJsonBody(request) {
27:   const chunks = [];
28:   for await (const chunk of request) chunks.push(chunk);
29:   if (!chunks.length) return {};
30:   return JSON.parse(Buffer.concat(chunks).toString("utf8"));
31: }
32: 
33: function sendJson(response, status, value) {
34:   response.writeHead(status, { "content-type": "application/json; charset=utf-8" });
35:   response.end(JSON.stringify(value));
36: }
37: 
38: const contentTypes = {
39:   ".css": "text/css; charset=utf-8",
40:   ".html": "text/html; charset=utf-8",
41:   ".js": "text/javascript; charset=utf-8",
42:   ".json": "application/json; charset=utf-8",
43:   ".png": "image/png",
44:   ".svg": "image/svg+xml",
45: };
46: 
47: const server = createServer(async (request, response) => {
48:   try {
49:     const url = new URL(request.url || "/", `http://${request.headers.host || "localhost"}`);
50:     if (url.pathname === "/api/health") {
51:       return sendJson(response, ready ? 200 : 503, { ready });
52:     }
53:     if (url.pathname === "/api/state" && request.method === "GET") {
54:       return sendJson(response, 200, await readState());
55:     }
56:     if (url.pathname === "/api/state" && ["PUT", "POST"].includes(request.method || "")) {
57:       const previous = await readState();
58:       const next = { ...previous, ...(await readJsonBody(request)) };
59:       const temporary = `${statePath}.tmp`;
60:       await writeFile(temporary, JSON.stringify(next, null, 2));
61:       await import("node:fs/promises").then(({ rename }) => rename(temporary, statePath));
62:       return sendJson(response, 200, next);
63:     }
64:     const requested = url.pathname === "/" ? "index.html" : url.pathname.replace(/^\/+/, "");
65:     let resolved = path.resolve(publicDir, requested);
66:     if (!resolved.startsWith(publicDir + path.sep)) resolved = path.join(publicDir, "index.html");
67:     let body;
68:     try {
69:       body = await readFile(resolved);
70:     } catch {
71:       resolved = path.join(publicDir, "index.html");
72:       body = await readFile(resolved);
73:     }
74:     response.writeHead(200, { "content-type": contentTypes[path.extname(resolved)] || "application/octet-stream" });
75:     response.end(body);
76:   } catch (error) {
77:     sendJson(response, 500, { error: error.message });
78:   }
79: });
80: 
81: server.listen(port, host, () => console.log(`listening on ${host}:${port}`));

